codeExample.code:
// File: HelloJava.java
// This program demonstrates the simplest Java application
// to understand the structure the JVM will execute.

public class HelloJava {

    // The JVM always looks for this exact main method to start
    public static void main(String[] args) {

        // Print a message to the console
        System.out.println("Hello, Java!");

        // Show Java version info at runtime
        String version = System.getProperty("java.version");
        System.out.println("Running on Java version: " + version);

        // Show operating system name
        String os = System.getProperty("os.name");
        System.out.println("Operating System: " + os);
    }
}

